  for (const locale of Object.values(locales)) {
    const progressTemplate = locale.onboarding.progress;
    locale.onboarding.progress = step => progressTemplate.replace("{step}", String(step));
    Object.freeze(locale.translations);
    Object.freeze(locale);
  }
  window.PHEISIRAETHA_LOCALES = Object.freeze(locales);
